from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one patch anchor, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


write("daedalus/kernel/attempts.py", '"""Lease-gated execution of the existing isolated attempt machinery.\n\nThis module is the Gate-0 strangler boundary for candidate-producing attempts.\nIt does not replace :mod:`daedalus.spine.attempt`; it binds that implementation\nto one authenticated EffectLease, one AttemptContract and one persisted\nexecution identity.  The legacy ``run_attempt`` import remains available for\ncallers that have not migrated and therefore remains a Gate-0 blocker.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any, Callable, Iterable, Mapping, Sequence\n\nfrom daedalus.kernel.contracts import EffectLease, EffectLeaseRequest\nfrom daedalus.kernel.effects import (\n    EffectExecutionRequest,\n    EffectLeaseLedger,\n    EffectStartResult,\n    EffectTerminalReceipt,\n    LeasedEffectStartReceipt,\n)\nfrom daedalus.schemas import AttemptContract, PolicyDecision, _repo_path\nfrom daedalus.spine.attempt import (\n    AttemptResult,\n    RunnerContext,\n    STATE_CANCELLED,\n    STATE_CLEAN,\n    STATE_GATES_FAILED,\n    STATE_NO_CHANGE,\n    TaskSpec,\n    run_attempt,\n)\nfrom daedalus.spine.effect_boundary import (\n    REGISTRY_BY_ID,\n    Effect,\n    EntrypointSpec,\n    GuardDecision,\n)\nfrom daedalus.spine.envelope import canonical_sha\n\nLEASED_ATTEMPT_ENTRYPOINT = "kernel.leased_attempt"\n_ATTEMPT_EFFECTS = tuple(\n    sorted(\n        (\n            Effect.FILESYSTEM_WRITE.value,\n            Effect.PROCESS_SPAWN.value,\n            Effect.REPOSITORY_MUTATION.value,\n        )\n    )\n)\n_COMPLETED_STATES = frozenset(\n    {STATE_CLEAN, STATE_GATES_FAILED, STATE_NO_CHANGE}\n)\n\n\nclass LeasedAttemptError(RuntimeError):\n    """Base class for an attempt refused by the lease integration boundary."""\n\n\nclass LeasedAttemptBindingError(LeasedAttemptError):\n    """The task, contract, lease or returned result are not the same attempt."""\n\n\n@dataclass(frozen=True)\nclass LeasedAttemptResult:\n    """One persisted effect start and, when executed, its terminal receipt.\n\n    ``execute`` is false on an exact replay.  In that case ``attempt`` is always\n    ``None``: replay can inspect the previously persisted terminal receipt but\n    can never call the underlying runner a second time.\n    """\n\n    start_receipt: LeasedEffectStartReceipt\n    terminal_receipt: EffectTerminalReceipt | None\n    attempt: AttemptResult | None\n    execute: bool\n    error: str | None = None\n\n    @property\n    def replayed(self) -> bool:\n        return not self.execute\n\n\ndef _normalized_paths(values: Sequence[str]) -> tuple[str, ...]:\n    return tuple(\n        sorted(\n            {\n                _repo_path(value, f"path[{index}]")\n                for index, value in enumerate(values)\n            }\n        )\n    )\n\n\ndef _bind_inputs(\n    task: TaskSpec,\n    attempt: AttemptContract,\n    request: EffectLeaseRequest,\n    policy: PolicyDecision,\n    lease: EffectLease,\n) -> None:\n    mismatches: list[str] = []\n    if task.task_id != attempt.task_id:\n        mismatches.append("task_id")\n    if task.digest != attempt.task_sha256:\n        mismatches.append("task_sha256")\n    if task.base_revision != attempt.base_revision:\n        mismatches.append("base_revision")\n    if _normalized_paths(task.target_paths) != attempt.writable_paths:\n        mismatches.append("writable_paths")\n    if attempt.read_only:\n        mismatches.append("read_only")\n    if request.entrypoint_id != LEASED_ATTEMPT_ENTRYPOINT:\n        mismatches.append("entrypoint_id")\n    if request.mission_id != attempt.mission_id:\n        mismatches.append("mission_id")\n    if request.attempt_id != attempt.attempt_id:\n        mismatches.append("attempt_id")\n    if request.provenance.source_revision != attempt.base_revision:\n        mismatches.append("request_source_revision")\n    if request.runtime_manifest_sha256 != attempt.runtime_manifest_sha256:\n        mismatches.append("runtime_manifest_sha256")\n    if request.runtime_conformance_sha256 is None:\n        mismatches.append("runtime_conformance_sha256")\n    if attempt.policy_decision_sha256 != policy.digest:\n        mismatches.append("policy_decision_sha256")\n    if tuple(request.requested_effects) != _ATTEMPT_EFFECTS:\n        mismatches.append("requested_effects")\n    if policy.subject_id != request.request_id:\n        mismatches.append("policy_subject_id")\n    if policy.subject_sha256 != request.digest:\n        mismatches.append("policy_subject_sha256")\n    if policy.effect_scope != request.effect_scope:\n        mismatches.append("policy_effect_scope")\n    if lease.request_id != request.request_id or lease.request_sha256 != request.digest:\n        mismatches.append("lease_request")\n    if lease.policy_decision_sha256 != policy.digest:\n        mismatches.append("lease_policy_decision")\n    if lease.entrypoint_id != request.entrypoint_id:\n        mismatches.append("lease_entrypoint")\n    if lease.runtime_manifest_sha256 != request.runtime_manifest_sha256:\n        mismatches.append("lease_runtime_manifest")\n    if lease.runtime_conformance_sha256 != request.runtime_conformance_sha256:\n        mismatches.append("lease_runtime_conformance")\n    if mismatches:\n        raise LeasedAttemptBindingError(\n            "leased attempt input binding mismatch: " + ", ".join(sorted(mismatches))\n        )\n\n\ndef _candidate_locator_bound(result: AttemptResult) -> bool:\n    artifact = result.artifact\n    locator = result.artifact_locator\n    return bool(\n        artifact is not None\n        and not artifact.is_empty\n        and isinstance(locator, Mapping)\n        and locator.get("uri") == f"sha256:{artifact.diff_sha256}"\n        and isinstance(locator.get("locator_uri"), str)\n        and str(locator["locator_uri"]).startswith("artifact-locator:sha256:")\n    )\n\n\ndef _validate_result(\n    result: AttemptResult,\n    task: TaskSpec,\n    attempt: AttemptContract,\n) -> None:\n    mismatches: list[str] = []\n    if result.task_id != task.task_id:\n        mismatches.append("result.task_id")\n    if result.base_revision != attempt.base_revision:\n        mismatches.append("result.base_revision")\n    if result.artifact is not None:\n        if result.artifact.task_id != task.task_id:\n            mismatches.append("artifact.task_id")\n        if result.artifact.base_revision != attempt.base_revision:\n            mismatches.append("artifact.base_revision")\n        changed = _normalized_paths(result.artifact.changed_paths)\n        allowed = set(attempt.writable_paths)\n        if any(path not in allowed for path in changed):\n            mismatches.append("artifact.changed_paths")\n    if result.state == STATE_CLEAN:\n        if result.artifact is None or result.artifact.is_empty:\n            mismatches.append("clean_without_artifact")\n        if result.gates is None or not result.gates.passed:\n            mismatches.append("clean_without_passing_gate")\n        if not _candidate_locator_bound(result):\n            mismatches.append("clean_without_bound_cas_locator")\n        if result.persist_error:\n            mismatches.append("clean_with_persist_error")\n    if result.ledger_error:\n        mismatches.append("attempt_ledger_error")\n    if mismatches:\n        raise LeasedAttemptBindingError(\n            "leased attempt result binding mismatch: " + ", ".join(sorted(mismatches))\n        )\n\n\ndef _terminal_outcome(result: AttemptResult) -> str:\n    if result.state == STATE_CANCELLED:\n        return "CANCELLED"\n    if result.state in _COMPLETED_STATES:\n        return "COMPLETED"\n    return "FAILED"\n\n\ndef _output_digests(result: AttemptResult) -> tuple[str, ...]:\n    values: set[str] = set()\n    if result.artifact is not None:\n        values.add(result.artifact.diff_sha256)\n    if result.gates is not None:\n        values.add(result.gates.output_sha256)\n    return tuple(sorted(values))\n\n\ndef _failure_detail(error: str) -> str:\n    return canonical_sha({"leased_attempt_error": error})\n\n\ndef run_leased_attempt(\n    task: TaskSpec,\n    *,\n    attempt: AttemptContract,\n    lease_request: EffectLeaseRequest,\n    policy_decision: PolicyDecision,\n    lease: EffectLease,\n    effect_ledger: EffectLeaseLedger,\n    keyring: Mapping[str, bytes | str],\n    guard_decisions: Iterable[GuardDecision],\n    current_kill_switch_generation: int,\n    runner: Callable[[RunnerContext], Any],\n    artifact_dir: str | Path,\n    repo_root: str | Path | None = None,\n    gate: Callable[[RunnerContext], Any] | None = None,\n    ledger: Any = None,\n    ledger_path: str | Path | None = None,\n    cancel: Any = None,\n    worktree_manager: Any = None,\n    keep_worktree: bool = False,\n    reap: bool = True,\n    execution_id: str | None = None,\n    idempotency_key: str | None = None,\n    started_at: datetime | None = None,\n    finished_at: datetime | None = None,\n    registry: Mapping[str, EntrypointSpec] | Sequence[EntrypointSpec] = REGISTRY_BY_ID,\n) -> LeasedAttemptResult:\n    """Run one exact isolated attempt at most once.\n\n    The start receipt is committed before ``run_attempt`` is called.  An exact\n    replay returns the persisted receipt with ``execute=False`` and never calls\n    the runner again.  A clean attempt is accepted as a completed effect only\n    when its candidate bytes were durably persisted in the CAS and the locator\n    binds the exact patch digest.\n    """\n\n    if not isinstance(task, TaskSpec):\n        raise TypeError("task must be a TaskSpec")\n    if not isinstance(attempt, AttemptContract):\n        raise TypeError("attempt must be an AttemptContract")\n    if not callable(runner):\n        raise ValueError("leased attempt requires an explicit runner")\n    if artifact_dir is None:\n        raise ValueError("leased attempt requires a candidate artifact CAS root")\n\n    _bind_inputs(task, attempt, lease_request, policy_decision, lease)\n\n    execution = EffectExecutionRequest(\n        execution_id=execution_id or f"{attempt.attempt_id}:run",\n        idempotency_key=idempotency_key or f"{attempt.attempt_id}:candidate",\n        requested_effects=_ATTEMPT_EFFECTS,\n        writable_paths=attempt.writable_paths,\n        tools=lease.effect_scope.tools,\n        max_cost_microusd=0,\n        kill_switch_ref=lease.effect_scope.kill_switch_ref,\n        kill_switch_generation=current_kill_switch_generation,\n    )\n    start: EffectStartResult = effect_ledger.begin(\n        lease,\n        execution,\n        request=lease_request,\n        policy_decision=policy_decision,\n        keyring=keyring,\n        guard_decisions=guard_decisions,\n        current_kill_switch_generation=current_kill_switch_generation,\n        started_at=started_at,\n        registry=registry,\n    )\n    if not start.execute:\n        return LeasedAttemptResult(\n            start_receipt=start.receipt,\n            terminal_receipt=effect_ledger.terminal_receipt(start.receipt),\n            attempt=None,\n            execute=False,\n        )\n\n    try:\n        result = run_attempt(\n            task,\n            runner=runner,\n            repo_root=repo_root,\n            gate=gate,\n            ledger=ledger,\n            ledger_path=ledger_path,\n            cancel=cancel,\n            worktree_manager=worktree_manager,\n            keep_worktree=keep_worktree,\n            reap=reap,\n            artifact_dir=artifact_dir,\n        )\n        _validate_result(result, task, attempt)\n    except Exception as exc:\n        error = f"{type(exc).__name__}: {exc}"\n        terminal = effect_ledger.finish(\n            start.receipt,\n            outcome="FAILED",\n            detail_sha256=_failure_detail(error),\n            finished_at=finished_at,\n        )\n        return LeasedAttemptResult(\n            start_receipt=start.receipt,\n            terminal_receipt=terminal,\n            attempt=None,\n            execute=True,\n            error=error,\n        )\n\n    detail_sha256 = canonical_sha(result.to_dict())\n    terminal = effect_ledger.finish(\n        start.receipt,\n        outcome=_terminal_outcome(result),\n        output_digests=_output_digests(result),\n        detail_sha256=detail_sha256,\n        finished_at=finished_at,\n    )\n    return LeasedAttemptResult(\n        start_receipt=start.receipt,\n        terminal_receipt=terminal,\n        attempt=result,\n        execute=True,\n        error=None,\n    )\n')
write("tests/kernel/test_leased_attempts.py", 'from __future__ import annotations\n\nimport dataclasses\nimport sqlite3\nfrom datetime import datetime, timedelta, timezone\n\nimport pytest\n\nimport daedalus.kernel.attempts as leased_attempts\nfrom daedalus.kernel import (\n    EffectLeaseLedger,\n    EffectLeaseBindingMismatch,\n    EffectLeaseStateError,\n    LeasedAttemptBindingError,\n    issue_effect_lease,\n)\nfrom daedalus.kernel.contracts import EffectLeaseRequest\nfrom daedalus.schemas import (\n    AttemptContract,\n    ContractProvenance,\n    EffectScope,\n    PolicyDecision,\n    ResourceBudget,\n)\nfrom daedalus.spine.attempt import (\n    AttemptResult,\n    GateResult,\n    PatchArtifact,\n    STATE_CANCELLED,\n    STATE_CLEAN,\n    TaskSpec,\n)\nfrom daedalus.spine.effect_boundary import (\n    ENTRYPOINTS,\n    REGISTRY_BY_ID,\n    Effect,\n    GuardDecision,\n    Wiring,\n)\n\nREVISION = "a" * 40\nMANIFEST_SHA = "b" * 64\nCONFORMANCE_SHA = "c" * 64\nPOLICY_SHA = "d" * 64\nSECRET = b"leased-attempt-issuer-secret-material-32-bytes"\nNOW = datetime(2026, 8, 3, 20, 0, tzinfo=timezone.utc)\n\n\ndef provenance(*inputs: str, created_at: datetime = NOW) -> ContractProvenance:\n    return ContractProvenance(\n        origin="tests.leased-attempt",\n        source_revision=REVISION,\n        created_at=created_at.isoformat(),\n        input_digests=tuple(inputs),\n        trace_id="mission-leased-attempt",\n    )\n\n\ndef task() -> TaskSpec:\n    return TaskSpec(\n        task_id="work-1",\n        instruction="Change src/value.py without touching the primary checkout.",\n        base_revision=REVISION,\n        target_paths=("src/value.py",),\n        gate_paths=("tests/test_value.py",),\n    )\n\n\ndef request() -> EffectLeaseRequest:\n    return EffectLeaseRequest(\n        request_id="lease-request-1",\n        mission_id="mission-1",\n        attempt_id="attempt-1",\n        entrypoint_id=leased_attempts.LEASED_ATTEMPT_ENTRYPOINT,\n        requested_effects=(\n            Effect.FILESYSTEM_WRITE.value,\n            Effect.PROCESS_SPAWN.value,\n            Effect.REPOSITORY_MUTATION.value,\n        ),\n        effect_scope=EffectScope(\n            read_only=False,\n            writable_paths=("src/value.py",),\n            tools=("git", "python"),\n            max_cost_microusd=0,\n            max_concurrency=1,\n            timeout_s=60,\n            kill_switch_ref="mission-1-kill",\n        ),\n        idempotency_namespace="mission-1-attempt-1",\n        kill_switch_generation=4,\n        runtime_manifest_sha256=MANIFEST_SHA,\n        runtime_conformance_sha256=CONFORMANCE_SHA,\n        provenance=provenance(MANIFEST_SHA, CONFORMANCE_SHA),\n    )\n\n\ndef policy(req: EffectLeaseRequest) -> PolicyDecision:\n    return PolicyDecision(\n        decision_id="policy-1",\n        subject_id=req.request_id,\n        subject_sha256=req.digest,\n        policy_version="2026-08-03",\n        policy_sha256=POLICY_SHA,\n        verdict="allow",\n        reasons=("isolated bounded candidate attempt",),\n        effect_scope=req.effect_scope,\n        provenance=provenance(req.digest, POLICY_SHA),\n    )\n\n\ndef attempt(selected_task: TaskSpec, selected_policy: PolicyDecision) -> AttemptContract:\n    return AttemptContract.from_task_spec(\n        selected_task,\n        attempt_id="attempt-1",\n        mission_id="mission-1",\n        runtime_manifest_sha256=MANIFEST_SHA,\n        policy_decision_sha256=selected_policy.digest,\n        budget=ResourceBudget(\n            max_tokens=1000,\n            max_cost_microusd=0,\n            max_wall_time_s=60,\n            max_attempts=1,\n        ),\n        provenance=provenance(\n            selected_task.digest,\n            MANIFEST_SHA,\n            selected_policy.digest,\n        ),\n    )\n\n\ndef guards() -> tuple[GuardDecision, ...]:\n    return (\n        GuardDecision(\n            "containment.attempt",\n            True,\n            "artifact-locator:sha256:" + "e" * 64,\n        ),\n        GuardDecision(\n            "spine.intent_ledger",\n            True,\n            "artifact-locator:sha256:" + "f" * 64,\n        ),\n    )\n\n\ndef clean_result(selected_task: TaskSpec) -> AttemptResult:\n    diff = b"diff --git a/src/value.py b/src/value.py\\n"\n    import hashlib\n\n    artifact = PatchArtifact(\n        task_id=selected_task.task_id,\n        branch="daedalus-attempt-work-1",\n        base_revision=REVISION,\n        diff_bytes=diff,\n        diff_sha256=hashlib.sha256(diff).hexdigest(),\n        changed_paths=("src/value.py",),\n        created_ts=(NOW + timedelta(seconds=1)).isoformat(),\n    )\n    gate = GateResult(\n        passed=True,\n        name="pytest",\n        command=("python", "-m", "pytest"),\n        returncode=0,\n        output="1 passed",\n        duration_s=0.1,\n    )\n    return AttemptResult(\n        state=STATE_CLEAN,\n        task_id=selected_task.task_id,\n        started_ts=NOW.isoformat(),\n        finished_ts=(NOW + timedelta(seconds=1)).isoformat(),\n        duration_s=1.0,\n        effect_key="daedalus-attempt-work-1",\n        branch="daedalus-attempt-work-1",\n        base_revision=REVISION,\n        artifact=artifact,\n        gates=gate,\n        worktree_removed=True,\n        artifact_locator={\n            "uri": f"sha256:{artifact.diff_sha256}",\n            "locator_uri": "artifact-locator:sha256:" + "9" * 64,\n        },\n    )\n\n\ndef setup_lease(tmp_path):\n    selected_task = task()\n    req = request()\n    selected_policy = policy(req)\n    selected_attempt = attempt(selected_task, selected_policy)\n    value = issue_effect_lease(\n        req,\n        selected_policy,\n        lease_id="lease-1",\n        issuer_key_id="kernel-key-1",\n        issued_at=NOW,\n        expires_at=NOW + timedelta(minutes=10),\n        secret=SECRET,\n        registry=REGISTRY_BY_ID,\n    )\n    ledger = EffectLeaseLedger(tmp_path / "effect-leases.sqlite3")\n    ledger.grant(\n        value,\n        request=req,\n        policy_decision=selected_policy,\n        keyring={"kernel-key-1": SECRET},\n        current_kill_switch_generation=4,\n        granted_at=NOW + timedelta(milliseconds=1),\n        registry=REGISTRY_BY_ID,\n    )\n    return selected_task, req, selected_policy, selected_attempt, value, ledger\n\n\ndef run(\n    tmp_path,\n    monkeypatch,\n    *,\n    fake_result: AttemptResult | None = None,\n    selected_task: TaskSpec | None = None,\n    req: EffectLeaseRequest | None = None,\n    selected_policy: PolicyDecision | None = None,\n    selected_attempt: AttemptContract | None = None,\n    lease=None,\n    effect_ledger=None,\n    calls=None,\n):\n    if effect_ledger is None:\n        (\n            default_task,\n            default_req,\n            default_policy,\n            default_attempt,\n            default_lease,\n            effect_ledger,\n        ) = setup_lease(tmp_path)\n        selected_task = selected_task or default_task\n        req = req or default_req\n        selected_policy = selected_policy or default_policy\n        selected_attempt = selected_attempt or default_attempt\n        lease = lease or default_lease\n    assert selected_task is not None\n    assert req is not None\n    assert selected_policy is not None\n    assert selected_attempt is not None\n    assert lease is not None\n    result = fake_result or clean_result(selected_task)\n    call_log = calls if calls is not None else []\n\n    def fake_run_attempt(*args, **kwargs):\n        call_log.append((args, kwargs))\n        return result\n\n    monkeypatch.setattr(leased_attempts, "run_attempt", fake_run_attempt)\n    output = leased_attempts.run_leased_attempt(\n        selected_task,\n        attempt=selected_attempt,\n        lease_request=req,\n        policy_decision=selected_policy,\n        lease=lease,\n        effect_ledger=effect_ledger,\n        keyring={"kernel-key-1": SECRET},\n        guard_decisions=guards(),\n        current_kill_switch_generation=4,\n        runner=lambda _ctx: None,\n        artifact_dir=tmp_path / "cas",\n        repo_root=tmp_path / "repo",\n        started_at=NOW + timedelta(seconds=1),\n        finished_at=NOW + timedelta(seconds=2),\n        registry=REGISTRY_BY_ID,\n    )\n    return output, call_log\n\n\ndef test_registry_has_one_central_leased_attempt_without_upgrading_legacy() -> None:\n    row = REGISTRY_BY_ID[leased_attempts.LEASED_ATTEMPT_ENTRYPOINT]\n    assert row.target == "daedalus.kernel.attempts:run_leased_attempt"\n    assert row.wiring is Wiring.CENTRAL\n    assert row.runtime_id == "isolated_attempt"\n    assert set(row.guard_contracts) == {\n        "containment.attempt",\n        "spine.intent_ledger",\n    }\n    assert REGISTRY_BY_ID["python.attempt"].wiring is Wiring.LOCAL_GUARDS\n    assert len([item for item in ENTRYPOINTS if item.id == row.id]) == 1\n\n\ndef test_first_start_persists_before_execution_and_exact_replay_never_runs_again(\n    tmp_path, monkeypatch\n) -> None:\n    selected_task, req, selected_policy, selected_attempt, lease, ledger = setup_lease(\n        tmp_path\n    )\n    calls = []\n    first, calls = run(\n        tmp_path,\n        monkeypatch,\n        selected_task=selected_task,\n        req=req,\n        selected_policy=selected_policy,\n        selected_attempt=selected_attempt,\n        lease=lease,\n        effect_ledger=ledger,\n        calls=calls,\n    )\n    second, calls = run(\n        tmp_path,\n        monkeypatch,\n        selected_task=selected_task,\n        req=req,\n        selected_policy=selected_policy,\n        selected_attempt=selected_attempt,\n        lease=lease,\n        effect_ledger=ledger,\n        calls=calls,\n    )\n\n    assert first.execute is True\n    assert first.attempt is not None\n    assert first.terminal_receipt is not None\n    assert first.terminal_receipt.outcome == "COMPLETED"\n    assert second.execute is False\n    assert second.attempt is None\n    assert second.start_receipt == first.start_receipt\n    assert second.terminal_receipt == first.terminal_receipt\n    assert len(calls) == 1\n    assert ledger.execution_state("attempt-1:run") == "COMPLETED"\n\n\n@pytest.mark.parametrize(\n    "mutation,expected",\n    [\n        ("task_digest", "task_sha256"),\n        ("base_revision", "base_revision"),\n        ("mission", "mission_id"),\n        ("runtime", "runtime_manifest_sha256"),\n        ("conformance", "runtime_conformance_sha256"),\n    ],\n)\ndef test_contract_and_stale_revision_mutations_refuse_before_execution(\n    tmp_path, monkeypatch, mutation, expected\n) -> None:\n    selected_task, req, selected_policy, selected_attempt, lease, ledger = setup_lease(\n        tmp_path\n    )\n    if mutation == "task_digest":\n        selected_task = dataclasses.replace(\n            selected_task, instruction="A different task with a different digest."\n        )\n    elif mutation == "base_revision":\n        selected_task = dataclasses.replace(\n            selected_task, base_revision="2" * 40\n        )\n    elif mutation == "mission":\n        selected_attempt = dataclasses.replace(\n            selected_attempt, mission_id="mission-other"\n        )\n    elif mutation == "runtime":\n        selected_attempt = dataclasses.replace(\n            selected_attempt,\n            runtime_manifest_sha256="3" * 64,\n            provenance=provenance(\n                selected_task.digest,\n                "3" * 64,\n                selected_policy.digest,\n            ),\n        )\n    elif mutation == "conformance":\n        req = dataclasses.replace(\n            req,\n            runtime_conformance_sha256="4" * 64,\n            provenance=provenance(MANIFEST_SHA, "4" * 64),\n        )\n        selected_policy = policy(req)\n        selected_attempt = attempt(selected_task, selected_policy)\n\n    called = []\n    monkeypatch.setattr(\n        leased_attempts,\n        "run_attempt",\n        lambda *a, **k: called.append((a, k)),\n    )\n    with pytest.raises(LeasedAttemptBindingError, match=expected):\n        leased_attempts.run_leased_attempt(\n            selected_task,\n            attempt=selected_attempt,\n            lease_request=req,\n            policy_decision=selected_policy,\n            lease=lease,\n            effect_ledger=ledger,\n            keyring={"kernel-key-1": SECRET},\n            guard_decisions=guards(),\n            current_kill_switch_generation=4,\n            runner=lambda _ctx: None,\n            artifact_dir=tmp_path / "cas",\n            registry=REGISTRY_BY_ID,\n        )\n    assert not called\n    assert ledger.execution_state("attempt-1:run") is None\n\n\ndef test_changed_registry_and_scope_escape_fail_closed(tmp_path, monkeypatch) -> None:\n    selected_task, req, selected_policy, selected_attempt, lease, ledger = setup_lease(\n        tmp_path\n    )\n    changed = dict(REGISTRY_BY_ID)\n    changed_row = dataclasses.replace(\n        changed[leased_attempts.LEASED_ATTEMPT_ENTRYPOINT],\n        notes="changed after lease issue",\n    )\n    changed[changed_row.id] = changed_row\n    with pytest.raises(EffectLeaseBindingMismatch, match="registry changed"):\n        leased_attempts.run_leased_attempt(\n            selected_task,\n            attempt=selected_attempt,\n            lease_request=req,\n            policy_decision=selected_policy,\n            lease=lease,\n            effect_ledger=ledger,\n            keyring={"kernel-key-1": SECRET},\n            guard_decisions=guards(),\n            current_kill_switch_generation=4,\n            runner=lambda _ctx: None,\n            artifact_dir=tmp_path / "cas",\n            registry=changed,\n        )\n\n    escaped_task = dataclasses.replace(\n        selected_task, target_paths=("src/value.py", "../outside")\n    )\n    escaped_attempt = dataclasses.replace(\n        selected_attempt, writable_paths=("src/value.py",)\n    )\n    with pytest.raises((ValueError, LeasedAttemptBindingError)):\n        leased_attempts.run_leased_attempt(\n            escaped_task,\n            attempt=escaped_attempt,\n            lease_request=req,\n            policy_decision=selected_policy,\n            lease=lease,\n            effect_ledger=ledger,\n            keyring={"kernel-key-1": SECRET},\n            guard_decisions=guards(),\n            current_kill_switch_generation=4,\n            runner=lambda _ctx: None,\n            artifact_dir=tmp_path / "cas",\n            registry=REGISTRY_BY_ID,\n        )\n\n\ndef test_unbound_cas_locator_and_changed_path_end_in_failed_terminal(\n    tmp_path, monkeypatch\n) -> None:\n    selected_task, req, selected_policy, selected_attempt, lease, ledger = setup_lease(\n        tmp_path\n    )\n    bad = clean_result(selected_task)\n    assert bad.artifact is not None\n    bad = dataclasses.replace(\n        bad,\n        artifact=dataclasses.replace(\n            bad.artifact, changed_paths=("src/other.py",)\n        ),\n        artifact_locator={\n            "uri": "sha256:" + "0" * 64,\n            "locator_uri": "artifact-locator:sha256:" + "9" * 64,\n        },\n    )\n    output, calls = run(\n        tmp_path,\n        monkeypatch,\n        fake_result=bad,\n        selected_task=selected_task,\n        req=req,\n        selected_policy=selected_policy,\n        selected_attempt=selected_attempt,\n        lease=lease,\n        effect_ledger=ledger,\n    )\n    assert len(calls) == 1\n    assert output.execute is True\n    assert output.attempt is None\n    assert output.error is not None\n    assert "artifact.changed_paths" in output.error\n    assert output.terminal_receipt is not None\n    assert output.terminal_receipt.outcome == "FAILED"\n\n\ndef test_cancelled_attempt_is_terminal_and_does_not_masquerade_as_success(\n    tmp_path, monkeypatch\n) -> None:\n    selected_task, req, selected_policy, selected_attempt, lease, ledger = setup_lease(\n        tmp_path\n    )\n    cancelled = dataclasses.replace(\n        clean_result(selected_task),\n        state=STATE_CANCELLED,\n        artifact=None,\n        gates=None,\n        artifact_locator=None,\n        error="cancelled",\n    )\n    output, _calls = run(\n        tmp_path,\n        monkeypatch,\n        fake_result=cancelled,\n        selected_task=selected_task,\n        req=req,\n        selected_policy=selected_policy,\n        selected_attempt=selected_attempt,\n        lease=lease,\n        effect_ledger=ledger,\n    )\n    assert output.error is None\n    assert output.attempt == cancelled\n    assert output.terminal_receipt is not None\n    assert output.terminal_receipt.outcome == "CANCELLED"\n\n\ndef test_corrupt_persisted_terminal_receipt_is_refused_on_replay(\n    tmp_path, monkeypatch\n) -> None:\n    selected_task, req, selected_policy, selected_attempt, lease, ledger = setup_lease(\n        tmp_path\n    )\n    first, _calls = run(\n        tmp_path,\n        monkeypatch,\n        selected_task=selected_task,\n        req=req,\n        selected_policy=selected_policy,\n        selected_attempt=selected_attempt,\n        lease=lease,\n        effect_ledger=ledger,\n    )\n    assert first.terminal_receipt is not None\n    with sqlite3.connect(ledger.path) as conn:\n        conn.execute(\n            "UPDATE effect_executions SET terminal_receipt_json=? "\n            "WHERE execution_id=?",\n            (\'{"corrupt":true}\', "attempt-1:run"),\n        )\n    with pytest.raises(EffectLeaseStateError, match="terminal receipt"):\n        run(\n            tmp_path,\n            monkeypatch,\n            selected_task=selected_task,\n            req=req,\n            selected_policy=selected_policy,\n            selected_attempt=selected_attempt,\n            lease=lease,\n            effect_ledger=ledger,\n        )\n')
write("docs/work-packets/G0-WP-04_LEASED_ATTEMPTS.md", '# G0-WP-04 — Lease-gated isolated attempts\n\n## Scope\n\nThis packet connects the existing hardened `TaskAttempt` implementation to the\npersisted Effect Lease boundary without replacing or renaming the legacy\nattempt module. It introduces one new centrally registered entrypoint:\n\n`daedalus.kernel.attempts:run_leased_attempt`\n\nThe existing `daedalus.spine.attempt:run_attempt` remains import-compatible and\nis deliberately still classified as `LOCAL_GUARDS`. Existing callers are not\nsilently upgraded; they remain visible migration work for Gate 0.\n\n## Contract chain\n\nThe boundary requires exact agreement between:\n\n- `TaskSpec` and `AttemptContract`;\n- mission, attempt, base revision, task digest and writable paths;\n- runtime manifest and conformance digests;\n- `EffectLeaseRequest`, `PolicyDecision` and authenticated `EffectLease`;\n- the current canonical effect-entrypoint registry digest;\n- exact execution and idempotency identifiers.\n\nThe Effect Lease ledger commits the start receipt before `TaskAttempt` may\ncreate a worktree or spawn a process. An exact replay returns\n`execute=false`, retrieves the prior terminal receipt when present and never\ninvokes the runner again.\n\n## Candidate and terminal integrity\n\nA clean attempt is terminally completed only when:\n\n- the returned task and base revision match the contract;\n- all changed paths are inside the declared target paths;\n- a non-empty candidate patch exists;\n- the deterministic gate passed;\n- the candidate was persisted in the content-addressed store; and\n- the locator binds the exact patch SHA-256.\n\nMalformed or contradictory results produce a persisted `FAILED` terminal\nreceipt. Cancellation produces `CANCELLED`. `gates_failed` and `no_change`\nremain completed executions but are not successful candidates; nomination and\npromotion remain separate decisions.\n\n## Adversarial verification\n\nThe focused suite covers mutations that would:\n\n1. execute the runner again on exact replay;\n2. remove the task-digest binding;\n3. accept a stale base revision;\n4. substitute mission or runtime identity;\n5. replace the runtime-conformance digest;\n6. use a registry changed after lease issue;\n7. escape the declared writable paths;\n8. report a clean result without a digest-bound CAS locator;\n9. return changed paths outside the contract; or\n10. corrupt the persisted terminal receipt.\n\nThe hard evidence is the deterministic test and CI output. This document is not\nan approval or a security attestation.\n\n## Deliberate remaining boundary\n\nThis packet centralizes one isolated attempt start. It does not migrate\n`python.offload`, provider runtimes, web/file-bridge mutation paths or sealed\npromotion. A runner that uses network, spend or secrets still requires the\ncorresponding later runtime Effect Lease and OS sandbox packet. Gate 0 remains\nopen.\n\nIron Plan: **ALIGNED**  \nIron Gate: **0**  \nPromotion: **not requested**\n')
write("docs/reviews/G0-WP-04_ADVERSARIAL_REVIEW.md", '# Adversarial review — G0-WP-04\n\n## Review posture\n\nThe review treats the new wrapper as hostile glue between two already existing\nauthorities: the Effect Lease ledger and `TaskAttempt`. It does not accept a\nbuilder statement as evidence and checks whether the persisted start, actual\nexecution and terminal receipt can diverge.\n\n## Findings resolved in the packet\n\n1. **Replay could have exposed only a start receipt.** A validated terminal\n   lookup was added. Corrupt, missing or cross-execution terminal data now\n   refuses rather than returning a best-effort result.\n2. **A green legacy result could lack durable candidate bytes.** Clean results\n   now require a CAS locator whose content URI equals the patch digest.\n3. **The wrapper could have accepted a different task under the same attempt\n   identifier.** Task digest, base revision, mission, runtime, policy and paths\n   are checked before the persisted effect start.\n4. **A gate or runner could return a changed path outside the WorkItem.** The\n   returned artifact is independently checked against the canonical attempt\n   writable paths.\n5. **Registering the new boundary could have hidden legacy callers.** The new\n   central row is additive; `python.attempt` remains non-central.\n\n## Residual risk\n\nThe Effect Lease is a persisted logical authorization boundary, not an OS\nsandbox. `TaskAttempt` provides worktree containment and candidate-code gates\nprovide platform containment where available, but provider network/spend and\nDocker-wide enforcement remain later Gate-0 Work Packets. The new entrypoint\nmust not be used to claim those effects are centrally covered.\n\n## Evidence requested from CI\n\n- focused lease/attempt/registry tests on Python 3.10 and 3.12;\n- full suite on Linux and Windows;\n- deterministic hash-seed matrix;\n- isolated wheel install/import;\n- Iron Plan verification;\n- effect-boundary conformance remains fail-closed.\n\nReview disposition: **builder changes accepted for draft review; no merge or\npromotion authorization issued.**\n')
write(".github/workflows/gate0-leased-attempts.yml", 'name: Gate 0 Leased Attempts\n\non:\n  pull_request:\n    branches:\n      - g0/effect-leases\n    paths:\n      - "daedalus/kernel/**"\n      - "daedalus/spine/attempt.py"\n      - "daedalus/spine/effect_boundary.py"\n      - "tests/kernel/test_leased_attempts.py"\n      - "tests/kernel/test_effect_leases.py"\n      - "tests/test_effect_boundary.py"\n      - "tests/test_kernel_contracts.py"\n      - "docs/work-packets/G0-WP-04_LEASED_ATTEMPTS.md"\n      - "docs/reviews/G0-WP-04_ADVERSARIAL_REVIEW.md"\n      - ".github/workflows/gate0-leased-attempts.yml"\n  push:\n    branches:\n      - g0/leased-attempts\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: gate0-leased-attempts-${{ github.workflow }}-${{ github.ref }}\n  cancel-in-progress: true\n\njobs:\n  focused:\n    strategy:\n      fail-fast: false\n      matrix:\n        os: [ubuntu-latest, windows-latest]\n        python: ["3.10", "3.12"]\n        seed: ["0", "123456"]\n    runs-on: ${{ matrix.os }}\n    env:\n      PYTHONHASHSEED: ${{ matrix.seed }}\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: ${{ matrix.python }}\n      - run: python -m pip install --upgrade pip\n      - run: python -m pip install -e . pytest\n      - run: python tools/iron_plan_guard.py verify\n      - run: >-\n          python -m pytest -q\n          tests/kernel/test_leased_attempts.py\n          tests/kernel/test_effect_leases.py\n          tests/kernel/test_owner_approval.py\n          tests/gates/test_gate_report.py\n          tests/test_kernel_contracts.py\n          tests/test_effect_boundary.py\n          tests/test_gate0_faults_atalanta.py\n\n  full-suite:\n    strategy:\n      fail-fast: false\n      matrix:\n        os: [ubuntu-latest, windows-latest]\n    runs-on: ${{ matrix.os }}\n    env:\n      PYTHONHASHSEED: "123456"\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.12"\n      - run: python -m pip install --upgrade pip\n      - run: python -m pip install -e ".[test]" pytest\n      - run: python -m pytest -q -p no:cacheprovider\n\n  isolated-wheel:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.12"\n      - run: python -m pip install --upgrade pip build\n      - run: python -m build\n      - run: python -m venv /tmp/daedalus-wheel\n      - run: /tmp/daedalus-wheel/bin/pip install dist/*.whl\n      - working-directory: /tmp\n        run: >-\n          /tmp/daedalus-wheel/bin/python -c\n          "from daedalus.kernel import LeasedAttemptResult,\n          run_leased_attempt"\n')

