execution_state_anchor = """    def execution_state(self, execution_id: str) -> str | None:
"""
replace_once(
    "daedalus/kernel/effects.py",
    execution_state_anchor,
    '    def terminal_receipt(\n        self,\n        start_receipt: LeasedEffectStartReceipt,\n    ) -> EffectTerminalReceipt | None:\n        """Return the exact persisted terminal for a start receipt.\n\n        ``None`` means the execution is durably STARTED but not terminal.  A\n        malformed row or a receipt belonging to another execution fails closed;\n        replay callers never receive a best-effort reconstruction.\n        """\n\n        with self._connect() as conn:\n            row = conn.execute(\n                """\n                SELECT state, start_receipt_sha256, start_receipt_json,\n                       terminal_receipt_sha256, terminal_receipt_json\n                FROM effect_executions\n                WHERE execution_id=? AND lease_sha256=?\n                """,\n                (\n                    start_receipt.execution_id,\n                    start_receipt.lease_sha256,\n                ),\n            ).fetchone()\n        if row is None:\n            raise EffectLeaseStateError("unknown effect execution")\n        persisted_start = _decode_start_receipt(row["start_receipt_json"])\n        if (\n            row["start_receipt_sha256"] != start_receipt.receipt_sha256\n            or persisted_start != start_receipt\n        ):\n            raise EffectLeaseStateError(\n                "start receipt does not match persisted execution"\n            )\n        if row["state"] == "STARTED":\n            if (\n                row["terminal_receipt_sha256"] is not None\n                or row["terminal_receipt_json"] is not None\n            ):\n                raise EffectLeaseStateError(\n                    "started execution contains a terminal receipt"\n                )\n            return None\n        if row["state"] not in _TERMINAL_STATES:\n            raise EffectLeaseStateError(\n                "persisted effect execution has an unknown state"\n            )\n        raw = row["terminal_receipt_json"]\n        digest = row["terminal_receipt_sha256"]\n        if raw is None or digest is None:\n            raise EffectLeaseStateError(\n                "terminal execution is missing its terminal receipt"\n            )\n        terminal = _decode_terminal_receipt(raw)\n        if (\n            terminal.receipt_sha256 != digest\n            or terminal.start_receipt_sha256 != start_receipt.receipt_sha256\n            or terminal.execution_id != start_receipt.execution_id\n            or terminal.lease_sha256 != start_receipt.lease_sha256\n            or canonical_json(terminal.to_dict()) != raw\n            or terminal.outcome != row["state"]\n        ):\n            raise EffectLeaseStateError(\n                "persisted terminal receipt does not match its execution row"\n            )\n        return terminal\n\n' + execution_state_anchor,
)

